retained.definitionSource:
word customer.discounted-balance(customer: Customer) -> Money {
    effects none
    doc "For premium customers, subtracts one tenth of the balance truncated toward zero; other kinds keep their balance."
    let balance = customer::balance(customer);
    if customer::premium?(customer) {
        let minor-units = Money::value(balance);
        let discount = ::divide(minor-units, 10);
        Money::new(::subtract(minor-units, discount))
    } else {
        balance
    }
}

tests.source:
test customer.discounted-balance/premium-positive-fraction {
    Money::value(customer::discounted-balance(customer::new(id = CustomerId::new("00000000-0000-0000-0000-000000000001"), email = Email::new("buyer@example.com"), kind = "premium", balance = Money::new(1059), created-at = Instant::new("2026-01-01T12:00:00.0000000+00:00"))))
    => 954
}

