reset.definitionSource:
word customer.discounted-balance(customer: Customer) -> Money {
    effects none
    doc "For raw kind exactly premium, subtracts one tenth of the balance truncated toward zero; other kinds keep their balance."
    let balance = customer::balance(customer);
    if ::equals(customer::kind(customer), "premium") {
        let minor-units = Money::value(balance);
        let discount = ::divide(minor-units, 10);
        Money::new(::subtract(minor-units, discount))
    } else {
        balance
    }
}

